        border: none;
        border-top: 1px solid #ddd;
        margin: 2em 0 1em;
      }

      .notification__details {
        margin-bottom: 0;
        margin-top: 0;
      }

      .notificaton__mention {
        background-color: #f8e3ab;
        border-radius: 0.7em 0.2em 0.7em 0.2em;
        color: inherit;
        display: inline-flex;
        padding: 0.1em 0.3em;
      }

      .margin-block-end-double {
        margin-bottom: 2em;
      }

      .margin-block-start-double {
        margin-top: 2em;
      }

      .subtitle {
        font-size: 1.2em;
        font-weight: normal;
        margin-bottom: 1em;
        margin-top: 0.1em;
      }

      .title {
        font-size: 1.4em;
        font-weight: 900;
        margin-bottom: 0;
      }

      .txt-large {
        font-size: 1.2em;
      }
    </style>
  </head>

  <body>
    <table id="body">
      <%= yield %>
    </table>
  </body>
