import os, re, json
from collections import defaultdict

root = "app/views"
# Extract quoted attribute values that are user-facing
attr_names = r"(?:aria-label|aria-labelledby|aria-description|title|placeholder|alt|bridge_title|bridge-title|validation_message|aria:\s*\{\s*label)"

results = []
for dirpath, _, files in os.walk(root):
    for f in files:
        if not f.endswith((".erb", ".jbuilder", ".json.erb", ".text.erb")):
            continue
        path = os.path.join(dirpath, f)
        with open(path, encoding="utf-8") as fh:
            content = fh.read()
        # Find likely English text: quoted strings with spaces and letters
        for i, line in enumerate(content.splitlines(), 1):
            # skip comments
            if line.strip().startswith("<%#"):
                continue
            # quoted strings with at least one space or capital letter words
            for m in re.finditer(r'(["\'])((?:(?!\1).){3,})\1', line):
                s = m.group(2)
                if re.search(r'[A-Za-z]{3,}', s) and not s.startswith("http") and "<%= " not in s:
                    # skip CSS/JS-looking
                    if re.match(r'^[a-z0-9_\-:#.]+$', s):
                        continue
                    if s.startswith("--") or s.startswith("turbo:") or s.startswith("keydown") or "->" in s:
                        continue
                    if s.startswith("data-") or s.startswith("btn") or s.startswith("flex") or s.startswith("txt-"):
                        continue
                    if s.startswith("class") or "controller" in s[:20]:
                        continue
                    results.append((path, i, s[:120]))

# unique-ish
print(f"Total matches: {len(results)}")
# print first 200
for p,i,s in results[:250]:
    print(f"{p}:{i}: {s}")
